const fs = require\('fs'\);
const lines = fs.readFileSync\('/tmp/final_unused.txt','utf8'\).trim\(\).split\('\\n'\).filter\(Boolean\);
const dirs = {};
for \(const line of lines\) {
  const idx = line.lastIndexOf\('/'\);
  const d = idx >= 0 ? line.slice\(0, idx\) : '.';
  const fn = idx >= 0 ? line.slice\(idx+1\) : line;
  if \(!dirs[d]\) dirs[d] = [];
  dirs[d].push\(fn\);
}
const sortedKeys = Object.keys\(dirs\).sort\(\);
for \(const d of sortedKeys\) {
  console.log\('=== public/' + d + '/ \(' + dirs[d].length + ' files\) ==='\);
  dirs[d].sort\(\).forEach\(fn => console.log\('  public/' + d + '/' + fn\)\);
  console.log\(''\);
}
console.log\('TOTAL UNUSED: ' + lines.length + ' files'\);
")

